let sourceText='', profileAnalysis={};
let currentProfileStatus='draft', lastOverview=null, lastReport=null;
const $=id=>document.getElementById(id);
const fields=['jobs','adjacent_jobs','metiers_vises','locations','remote','contracts','sectors','exclusions','skills','sources','seniorite','career_pages','romes'];
const SKILL_LEVELS=['débutant','opérationnel','confirmé','expert','à confirmer'];
let noticeTimer=null;
function message(text,kind='ok'){const n=$('notice');n.textContent=text;n.className='notice '+kind;n.hidden=false;n.onclick=()=>{n.hidden=true};clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.hidden=true,kind==='error'?7000:4500)}
function split(value){return value.split(/[\n,]+/).map(x=>x.trim()).filter(Boolean)}
// « 0 offre », « 1 offre », « 3 offres » : accord français (0 et 1 au singulier).
function plural(n,one,many){n=Number(n)||0;return `${n.toLocaleString('fr-FR')} ${n>1?(many||one+'s'):one}`}
function fmtScore(v){const n=Number(v);return v==null||v===''||isNaN(n)?'—':n.toLocaleString('fr-FR',{maximumFractionDigits:1})}
function scoreClass(v){const n=Number(v);if(v==null||isNaN(n))return 'none';return n>=7?'high':n>=5?'mid':'low'}
function renderCvContext(data){const has=!!(data.main_job||data.secondary_job||data.profile_summary);$('main_job').value=data.main_job||'';$('secondary_job').value=data.secondary_job||'';$('profile_summary').value=data.profile_summary||'';$('cvContext').hidden=!has}
const WEIGHT_DIMS=[['competences','Compétences'],['intitule','Métier et missions'],['experience','Expérience'],['localisation','Lieu et télétravail'],['salaire','Salaire'],['contrat','Type de contrat'],['secteur','Secteur']];
const DEFAULT_WEIGHTS={competences:35,intitule:15,experience:10,localisation:15,salaire:10,contrat:10,secteur:5};
let weights={...DEFAULT_WEIGHTS};
function renderWeights(){const list=$('weightsList');list.innerHTML=WEIGHT_DIMS.map(([k,label])=>`<label class="weight"><span>${label}</span><input id="w_${k}" type="range" min="0" max="100" step="1" value="${weights[k]}" oninput="weightChange('${k}',this.value)"><em id="w_${k}_v">${weights[k]} %</em></label>`).join('');updateWeightTotal()}
function weightChange(k,v){weights[k]=Math.max(0,Math.min(100,Number(v)));const em=$('w_'+k+'_v');if(em)em.textContent=weights[k]+' %';updateWeightTotal()}
function updateWeightTotal(){const total=WEIGHT_DIMS.reduce((s,[k])=>s+weights[k],0);$('weightsTotal').textContent=total.toFixed(0)+' %';const st=$('weightsStatus');const ok=Math.abs(total-100)<0.6;st.textContent=ok?'✓':'✕';st.className=ok?'ok':'bad';st.title=ok?'Le total fait bien 100 %':`Le total fait ${total.toFixed(0)} % au lieu de 100 %`}
function resetWeights(){weights={...DEFAULT_WEIGHTS};WEIGHT_DIMS.forEach(([k])=>{const el=$('w_'+k);if(el)el.value=weights[k];const em=$('w_'+k+'_v');if(em)em.textContent=weights[k]+' %'});updateWeightTotal();message('Pondération remise aux valeurs par défaut.')}
function normalizeWeights(){const total=WEIGHT_DIMS.reduce((s,[k])=>s+weights[k],0);if(total<=0)return weights={...DEFAULT_WEIGHTS};const scale=100/total;WEIGHT_DIMS.forEach(([k])=>{weights[k]=Math.round(weights[k]*scale)});const rem=100-WEIGHT_DIMS.reduce((s,[k])=>s+weights[k],0);if(rem)weights[WEIGHT_DIMS[0][0]]+=rem;WEIGHT_DIMS.forEach(([k])=>{const el=$('w_'+k);if(el)el.value=weights[k];const em=$('w_'+k+'_v');if(em)em.textContent=weights[k]+' %'});updateWeightTotal();message('Pondération ramenée à 100 %.')}
function loadWeights(p){if(!p)p={};const f=p.ponderation||p.weights||{};WEIGHT_DIMS.forEach(([k])=>{weights[k]=f[k]!=null?Math.round(Number(f[k])*100):DEFAULT_WEIGHTS[k]});if(typeof renderWeights==='function')renderWeights()}
function weightsPayload(){const out={};WEIGHT_DIMS.forEach(([k])=>{out[k]=(weights[k]||0)/100});return out}
async function api(url,options={}){const headers={...(options.headers||{})};const tok=localStorage.getItem('jw_token');if(tok&&!headers.Authorization)headers.Authorization='Bearer '+tok;const r=await fetch(url,{...options,headers});let data=null;try{data=await r.json()}catch(e){data=null}if(r.status===401){updateAuthGate(null,true);throw new Error((data&&data.detail)||'Connectez-vous pour continuer.')}if(!r.ok)throw new Error((data&&data.detail)||'Une erreur est survenue.');return data}
async function authMe(){try{const r=await fetch('/api/auth/me',{headers:localStorage.getItem('jw_token')?{Authorization:'Bearer '+localStorage.getItem('jw_token')}:{}});return await r.json()}catch(e){return{user:null,auth:true}}}
// Le bandeau du haut n'affiche l'utilisateur (et la déconnexion) que s'il y a un
// compte connecté : en mode mono-utilisateur, il n'y a rien à afficher.
function updateAuthGate(me,forceGate){const gate=$('authGate');const main=$('appMain');const bar=$('authBar');const needGate=forceGate||(me&&me.auth!==false&&!me.user);if(gate)gate.hidden=!needGate;if(main)main.hidden=!!needGate;const cta=$('campaignBtn');if(cta)cta.hidden=!!needGate;if(bar){const user=!needGate&&me&&me.user;bar.hidden=!user;if(user){$('authState').textContent=me.user.username;$('authState').title='Connecté en tant que '+me.user.username}}return!needGate}
async function doLogin(mode){const u=$('authUser').value.trim();const p=$('authPass').value;if(!u||!p){authMessage('Saisissez votre identifiant et votre mot de passe.','error');return}try{const r=await fetch('/api/auth/'+mode,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:u,password:p})});const data=await r.json();if(!r.ok)throw new Error(data.detail||'Connexion impossible. Réessayez.');localStorage.setItem('jw_token',data.token);boot();message(mode==='register'?'Compte créé, bienvenue '+data.username+' !':'Connecté en tant que '+data.username+'.')}catch(e){authMessage(e.message,'error')}}
function authMessage(text,kind){const n=$('noticeAuth');if(!n)return message(text,kind);n.textContent=text;n.className='notice inline '+kind;n.hidden=false}
async function doLogout(){try{await api('/api/auth/logout',{method:'POST'})}catch(e){}localStorage.removeItem('jw_token');location.reload()}
async function showAuth(force){let me={user:null,auth:true};if(!force){try{me=await authMe()}catch(e){me={user:null,auth:true}}}const gate=$('authGate');if(gate&&$('authPass')){if(force&&gate.hidden)gate.hidden=false;if(!gate.hidden)setTimeout(()=>{const el=$('authUser');if(el)el.focus()},50)}return updateAuthGate(me,force)}
async function boot(){let me={user:null,auth:true};try{me=await authMe()}catch(e){me={user:null,auth:true}}const ok=updateAuthGate(me,false);if(!ok)return;bindJobFilters();renderWeights();Promise.all([loadProfile(),loadOverview(),loadJobs(),loadApplications()]).then(()=>showTab(currentProfileStatus==='validated'?'tracking':'profile')).catch(e=>message(e.message,'error'))}
function showTab(name){document.querySelectorAll('.tab,.panel').forEach(x=>{x.classList.remove('active');x.removeAttribute('aria-current')});const btn=document.querySelector(`.tab[data-tab="${name}"]`);if(btn){btn.classList.add('active');btn.setAttribute('aria-current','page')}const panel=$(name);if(panel)panel.classList.add('active');autoSizeDossierTextareas();if(name==='tracking')loadKanban()}
document.querySelectorAll('.tab').forEach(button=>button.onclick=()=>showTab(button.dataset.tab));
// Textareas de la page candidature (dossier) : hauteur automatique selon le
// contenu, sans jamais descendre sous la hauteur initiale liée à l'attribut rows.
// Plafond à 60 % de la fenêtre : au-delà, le champ défile au lieu d'allonger la page
// (un CV complet faisait plusieurs écrans de haut).
function autoSizeTextarea(el){if(!el||el.tagName!=='TEXTAREA'||!el.clientHeight)return;if(!el.dataset.autosizeFloor)el.dataset.autosizeFloor=String(el.clientHeight);const floor=Number(el.dataset.autosizeFloor);const cap=Math.max(floor,Number(el.dataset.autosizeMax)||Math.round(window.innerHeight*.6));el.style.height='auto';el.style.height=(Math.min(Math.max(el.scrollHeight,floor),cap)+(el.offsetHeight-el.clientHeight))+'px'}
function autoSizeDossierTextareas(){document.querySelectorAll('#dossierView textarea').forEach(autoSizeTextarea)}
document.addEventListener('input',e=>{if(e.target&&e.target.matches&&e.target.matches('#dossierView textarea'))autoSizeTextarea(e.target)});
window.addEventListener('resize',autoSizeDossierTextareas);
async function loadProfile(){const p=await api('/api/profile');sourceText=p.source_text||'';profileAnalysis=p.data||{};applyProfileData(profileAnalysis,p.name||'');setProfileStatus(p.status);if(sourceText)$('cvResult').textContent='Un CV a déjà été analysé. Importez-en un nouveau pour mettre la fiche à jour.'}
// Remplit la fiche à partir d'une analyse (CV importé ou affinage IA) : tous les
// champs du profil sont exposés, y compris secteurs, exclusions et salaires.
function applyProfileData(data,fallbackName=''){data=data||{};$('name').value=data.name||fallbackName||$('name').value||'';fields.forEach(k=>{const el=$(k);if(el)el.value=(data[k]||[]).join('\n')});$('jobs').value=[data.main_job,...(data.jobs||[]).filter(j=>j!==data.main_job&&j!==data.secondary_job)].concat(data.secondary_job?[data.secondary_job]:[]).filter(Boolean).join('\n');$('mobility').value=data.mobility||'';$('profile_summary').value=data.profile_summary||'';$('years_experience').value=data.years_experience??'';$('salary_min').value=data.salary_min??'';$('salary_max').value=data.salary_max??'';if($('max_age_days'))$('max_age_days').value=data.max_age_days??'';renderCvContext(data);renderMatrix();loadWeights(data)}
function setProfileStatus(status){currentProfileStatus=status;const ready=status==='validated';$('profileStatus').textContent=ready?'Validé':'À valider';$('profileBadge').textContent=ready?'Profil validé':'Brouillon';$('profileBadge').className='badge '+(ready?'ready':'');const flag=$('profileTabLabel');if(flag)flag.hidden=ready}
// La matrice est la source unique du détail (catégorie, niveau, preuve) : la
// liste « Compétences » est sa projection plate. Toute compétence ajoutée à la
// main reçoit une ligne dédiée, toute ligne supprimée disparaît.
function syncSkillMatrix(skills,matrix){const norm=v=>String(v||'').trim().toLowerCase();const kept=(matrix||[]).filter(r=>r&&r.skill&&skills.some(s=>norm(s)===norm(r.skill)));const known=new Set(kept.map(r=>norm(r.skill)));skills.forEach(s=>{if(!known.has(norm(s))){kept.push({skill:s,category:'Autre',level:'à confirmer',evidence:'À confirmer dans le CV'});known.add(norm(s))}});return kept}
function payload(validated){const data={name:profileAnalysis.name||'',main_job:profileAnalysis.main_job||'',secondary_job:profileAnalysis.secondary_job||'',mobility:$('mobility').value.trim(),years_experience:$('years_experience').value?Number($('years_experience').value):null,salary_min:$('salary_min').value?Number($('salary_min').value):null,salary_max:$('salary_max').value?Number($('salary_max').value):null,max_age_days:$('max_age_days')?.value?Number($('max_age_days').value):null,skill_matrix:syncSkillMatrix(split($('skills').value),profileAnalysis.skill_matrix||[]),profile_summary:$('profile_summary').value.trim(),ponderation:weightsPayload()};fields.forEach(k=>data[k]=split($(k).value));return {name:$('name').value.trim()||'Candidat',data,validate_profile:validated,source_text:sourceText}}
async function saveProfile(event,validated,button){if(event)event.preventDefault();const btn=button||(event&&event.submitter)||null;const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent=validated?'Validation…':'Enregistrement…'}try{const p=await api('/api/profile',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload(validated))});setProfileStatus(p.status);message(validated?'Profil validé. Vous pouvez lancer la veille.':'Brouillon enregistré. Validez le profil quand il est prêt.');loadOverview();if(validated)loadJobs()}catch(e){message(e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent=idle}}}
// Matrice regroupée par domaine : chaque ligne expose le niveau (modifiable) et
// la preuve tirée du CV, pour que l'utilisateur voie tout ce qui a été extrait.
function renderMatrix(){const el=$('skillMatrix'),summary=$('matrixSummary');const matrix=profileAnalysis.skill_matrix||[];if(summary)summary.textContent=matrix.length?`Compétences détectées (${matrix.length})`:'Compétences détectées';if(!el)return;if(!matrix.length){el.innerHTML='<p class="hint">Aucune compétence détectée. Importez votre CV pour remplir cette liste.</p>';return}const groups=[];matrix.forEach((row,i)=>{const cat=row.category||'Autre';let g=groups.find(x=>x.category===cat);if(!g){g={category:cat,rows:[]};groups.push(g)}g.rows.push({row,i})});el.innerHTML=groups.map(g=>`<section class="matrix-group"><h4>${safe(g.category)} <span class="matrix-count">${g.rows.length}</span></h4>${g.rows.map(({row,i})=>`<div class="matrix-row"><div class="matrix-line"><strong>${safe(row.skill)}</strong><select class="select matrix-level" aria-label="Niveau de ${safe(row.skill)}" onchange="setMatrixField(${i},'level',this.value)">${SKILL_LEVELS.map(l=>`<option value="${l}" ${l===row.level?'selected':''}>${l}</option>`).join('')}</select><input class="matrix-category" value="${safe(row.category||'')}" aria-label="Catégorie de ${safe(row.skill)}" onchange="setMatrixField(${i},'category',this.value)"></div><small>${safe(row.evidence)}</small></div>`).join('')}</section>`).join('')}
function setMatrixField(index,field,value){const row=(profileAnalysis.skill_matrix||[])[index];if(!row)return;row[field]=value;if(field==='category')renderMatrix()}
async function importCv(){const file=$('cvFile').files[0];if(!file)return;const label=document.querySelector('.dropzone strong');label.textContent=file.name;const fd=new FormData();fd.append('file',file);$('cvResult').className='analysis';$('cvResult').textContent='Analyse du CV en cours…';agentFeedStart('Import du CV');try{const r=await streamPost('/api/cv/import/stream',{method:'POST',body:fd},evt=>{if(evt.type==='progress')agentFeedEvent(evt)});agentFeedStep('CV analysé : relisez la fiche avant de la valider.','done');agentFeedFinish();sourceText=r.source_text;profileAnalysis=r.data;applyProfileData(r.data);$('cvResult').innerHTML='<strong>CV analysé</strong> <small class="hint">('+safe(r.analysis.provider)+')</small><br>'+safe(r.data.profile_summary||'Relisez les informations détectées.')+(r.note?'<br><small class="hint">'+safe(r.note)+'</small>':'');message('CV analysé. Relisez la fiche avant de la valider.')}catch(e){agentFeedStep(e.message,'error');agentFeedFinish('error');$('cvResult').className='analysis empty';$('cvResult').textContent=e.message;message(e.message,'error')}}
async function aiRefineProfile(btn){const promptEl=$('profileAiPrompt');const instruction=promptEl?promptEl.value.trim():'';if(!instruction){message('Décrivez d’abord le changement souhaité.','error');if(promptEl)promptEl.focus();return}const status=$('profileAiStatus');const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Ajustement…'}if(status)status.textContent='L’IA ajuste la fiche à partir de votre CV…';agentFeedStart('Ajustement du profil');try{const body={instruction,name:$('name').value.trim()||'Candidat',data:payload(false).data,source_text:sourceText};const r=await streamPost('/api/profile/refine/stream',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)},evt=>{if(evt.type==='progress')agentFeedEvent(evt)});profileAnalysis=r.data||{};applyProfileData(profileAnalysis,r.data?.name||'');if(status)status.textContent=[r.changes_summary,r.warning||(r.applied?'Fiche mise à jour : relisez-la, puis enregistrez ou validez.':'')].filter(Boolean).join(' ');const noEffect='Aucune modification : '+(r.warning||'la consigne n’a rien changé.');agentFeedStep(r.applied?'Fiche ajustée : relisez-la, puis enregistrez ou validez.':noEffect,r.applied?'done':'error');agentFeedFinish(r.applied?'done':'error');message(r.applied?'Fiche ajustée. Relisez-la, puis enregistrez ou validez.':noEffect,r.applied?'ok':'error')}catch(e){agentFeedStep(e.message,'error');agentFeedFinish('error');if(status)status.textContent='';message(e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent=idle}}}
function busy(btn,on,text){if(!btn)return;btn.disabled=on;btn.textContent=on?text:btn.dataset.idle||'Lancer la veille'}
async function streamPost(url,options,onEvent){options=options||{};const headers={...(options.headers||{})};const tok=localStorage.getItem('jw_token');if(tok&&!headers.Authorization)headers.Authorization='Bearer '+tok;const r=await fetch(url,{...options,headers});const ct=(r.headers.get('content-type')||'');if(!r.ok){let msg='Une erreur est survenue.';if(ct.includes('application/json')){try{msg=(await r.json()).detail||msg}catch(x){}}if(r.status===401)updateAuthGate(null,true);throw new Error(msg)}if(!ct.includes('text/event-stream')||!r.body){const data=await r.json();onEvent({type:'done',result:data});return data}const reader=r.body.getReader();const dec=new TextDecoder();let buf='',result=null,fail=null;const frame=f=>f.split('\n').forEach(line=>{if(!line.startsWith('data:'))return;try{const evt=JSON.parse(line.slice(5).trim());if(evt.type==='done')result=evt.result;else if(evt.type==='error')fail=new Error(evt.message||'Une erreur est survenue.');onEvent(evt)}catch(x){}});for(;;){const {done,value}=await reader.read();if(done)break;buf+=dec.decode(value,{stream:true});let i;while((i=buf.indexOf('\n\n'))>=0){frame(buf.slice(0,i));buf=buf.slice(i+2)}}if(buf.trim())frame(buf);if(fail)throw fail;return result}
let agentHideTimer=null;
function agentFeedStart(title){clearTimeout(agentHideTimer);const f=$('agentFeed');f.hidden=false;f.classList.remove('done','error');$('agentFeedTitle').textContent=title;$('agentFeedSteps').innerHTML='';agentFeedStep('Démarrage…')}
function agentFeedStep(text,state='current',detail=''){const steps=$('agentFeedSteps');const prev=steps.querySelector('li.current');if(prev){prev.classList.remove('current');prev.classList.add('done')}const li=document.createElement('li');li.className=state;li.textContent=text;if(detail){const d=document.createElement('small');d.textContent=detail;li.appendChild(d)}steps.appendChild(li);steps.scrollTop=steps.scrollHeight}
/* Événement de progression SSE → une ligne dans le fil d'activité : message du
   serveur, plus l'URL de la requête et/ou le détail d'échec quand ils existent. */
function agentFeedEvent(evt){const bad=['source_error','request_error'].includes(evt.step||'');const detail=[bad?(evt.error||''):'',evt.url||''].filter(Boolean).join(' · ');agentFeedStep(evt.message,bad?'error':'current',detail)}
function agentFeedFinish(state='done'){const f=$('agentFeed');f.classList.add(state);clearTimeout(agentHideTimer);agentHideTimer=setTimeout(()=>{f.hidden=true},state==='error'?10000:6000)}
function closeAgentFeed(){clearTimeout(agentHideTimer);$('agentFeed').hidden=true}
async function runCampaign(){const btn=$('campaignBtn');btn.dataset.idle='Lancer la veille';busy(btn,true,'Veille en cours…');const src='web';agentFeedStart('Veille des offres');try{const r=await streamPost('/api/campaign/run/stream?source='+src,{method:'POST'},evt=>{if(evt.type==='progress')agentFeedEvent(evt)});const found=plural(r.imported,'nouvelle offre','nouvelles offres');agentFeedStep(`Terminé : ${found}, ${r.shortlisted} à examiner.`,'done');agentFeedFinish();busy(btn,false);message(`Veille terminée : ${found} sur ${plural(r.processed,'offre analysée','offres analysées')}, ${r.shortlisted} à examiner.`);renderCampaignReport(r);renderMarketAnalysis(r.market_analysis);loadOverview();loadJobs();showTab('market')}catch(e){busy(btn,false);agentFeedStep(e.message,'error');agentFeedFinish('error');message(e.message,'error');showTab(currentProfileStatus==='validated'?'market':'profile')}}
function renderCampaignReport(r){
 const box=$('campaignReport');if(!r||!r.report){box.hidden=true;return}
 const s=r.report.sources||{}; const rows=Object.entries(s).map(([k,v])=>`<div><strong>${safe(SOURCE_LABELS[k]||k)}</strong><span class="${v.error?'error':'ok'}">${plural(v.count||0,'offre')}${v.error?' · '+safe(v.error):''}</span></div>`).join('')
 const raw=r.report.total_raw||0,uniq=r.report.total_unique||0;
 box.hidden=false;box.innerHTML=`<div class="card-head"><h3>Résultat de la veille</h3><button type="button" class="ghost small" onclick="this.closest('.report').hidden=true">Masquer</button></div><div class="report-grid">${rows||'<div>Aucune source interrogée.</div>'}</div><small class="hint">${plural(raw,'offre trouvée','offres trouvées')}, dont ${plural(uniq,'offre unique','offres uniques')} après suppression des doublons.</small>`
}
/* Ajout d'une annonce repérée soi-même : le lien est collé, la plateforme fait le
   reste (récupération, pré-notation, complétion, notation) et l'ajoute à la liste. */
function importUrlPayload(){const val=id=>{const el=$(id);return el?(el.value||'').trim():''};return {url:val('importUrl'),title:val('importTitle'),company:val('importCompany'),description:val('importDescription')}}
function importUrlReport(r){
 const rep=(r&&r.report)||{},j=(r&&r.job)||{};
 const rows=[['Note',rep.score!=null?fmtScore(rep.score)+'/10':''],['Intitulé',j.title],['Entreprise',j.company],['Lieu',j.location],['Contrat',j.contract],['Télétravail',j.remote],['Salaire',fmtSal(j.salary_min,j.salary_max)],['Source',SOURCE_LABELS[rep.source]||rep.source]].filter(([,v])=>String(v==null?'':v).trim());
 const grid=rows.map(([k,v])=>`<div><strong>${safe(k)}</strong><span>${safe(v)}</span></div>`).join('');
 const matched=(rep.matched_skills||[]).length?`<small class="hint">Compétences en commun : ${safe(rep.matched_skills.join(', '))}.</small>`:'';
 const gaps=(rep.gaps||[]).length?`<small class="hint">Demandées mais absentes de votre profil : ${safe(rep.gaps.join(', '))}.</small>`:'';
 const warn=(rep.warnings||[]).map(s=>`<small class="warning">${safe(s)}</small>`).join('');
 const link=j.url?`<a class="ghost link-btn small" href="${safe(j.url)}" target="_blank" rel="noopener">Voir l'annonce ↗</a>`:'';
 return `<h3>${rep.created?'Offre ajoutée à la liste':'Offre déjà connue, mise à jour'}</h3><div class="report-grid">${grid}</div>${matched}${gaps}${warn}${link?`<div class="form-actions spaced">${link}</div>`:''}`
}
async function importOfferUrl(){
 const payload=importUrlPayload();const btn=$('importUrlBtn');const box=$('importUrlResult');
 if(!payload.url){message('Collez d’abord le lien de l’offre.','error');const el=$('importUrl');if(el)el.focus();return}
 const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Analyse…'}
 if(box){box.hidden=false;box.className='analysis';box.textContent='Récupération et analyse de l’offre…'}
 agentFeedStart('Ajout d’une offre');
 try{
  const r=await streamPost('/api/jobs/import-url/stream',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)},evt=>{if(evt.type==='progress')agentFeedEvent(evt)});
  const rep=(r&&r.report)||{};
  agentFeedStep(`Offre ${rep.created?'ajoutée':'mise à jour'}, notée ${fmtScore(rep.score)}/10.`,'done');agentFeedFinish();
  if(box){box.className='analysis';box.innerHTML=importUrlReport(r)}
  $('importUrl').value='';
  message(`Offre ${rep.created?'ajoutée':'mise à jour'} : « ${(r.job||{}).title||'sans titre'} », notée ${fmtScore(rep.score)}/10.`);
  await Promise.all([loadJobs(),loadOverview()]);
  showTab('market')
 }catch(e){
  agentFeedStep(e.message,'error');agentFeedFinish('error');
  if(box){box.className='analysis empty';box.textContent=e.message}
  message(e.message,'error')
 }finally{if(btn){btn.disabled=false;btn.textContent=idle}}
}
function renderMarketAnalysis(a){
 const box=$('marketAnalysis');if(!a){box.hidden=true;return}
 const kw=(a.keywords||[]).map(s=>'<span>'+safe(s)+'</span>').join('')
 const sr=(a.seniorities||[]).map(s=>'<span>'+safe(s)+'</span>').join('')
 const ang=(a.angles||[]).map(s=>'<li>'+safe(s)+'</li>').join('')
 const hyp=(a.hypotheses||[]).map(s=>'<li>'+safe(s)+'</li>').join('')
 const f=a.facts||{};const scope=f.scope==='profil'?`<p class="hint">Basée sur les ${plural(f.jobs_count,'offre récente','offres récentes')} qui correspondent à votre profil (sur ${f.catalog_count} au total).</p>`:'';box.hidden=false;box.innerHTML=`<div class="card-head"><h3>Analyse du marché</h3><button type="button" class="ghost small" onclick="this.closest('.analysis').hidden=true">Masquer</button></div>${scope}<p>${safe(a.summary||'')}</p>`+(kw?`<h4>Mots-clés fréquents</h4><div class="chips">${kw}</div>`:'')+(sr?`<h4>Niveaux demandés</h4><div class="chips">${sr}</div>`:'')+(ang?`<h4>Pistes</h4><ul>${ang}</ul>`:'')+(hyp?`<h4>Hypothèses à vérifier</h4><ul class="warning">${hyp}</ul>`:'')
}
async function loadOverview(){const o=await api('/api/overview');lastOverview=o;$('jobsCount').textContent=o.jobs_count;$('shortlistCount').textContent=o.retained_count;$('applicationsCount').textContent=o.applications_count;setProfileStatus(o.profile_status);renderTrackingTodo();const m=o.market||{};const topSkill=(m.skills||[]).map(([skill])=>String(skill).trim()).find(skill=>skill.length>2&&/[a-zà-ÿ]/i.test(skill));const parts=[];if(m.scope==='profil')parts.push(`${plural(m.jobs_count,'offre correspond','offres correspondent')} à votre profil, sur ${m.catalog_count} au total.`);if(topSkill)parts.push(`Compétence la plus demandée : ${topSkill}.`);$('marketSummary').textContent=parts.join(' ')||'Parcourez les offres et retenez celles qui vous intéressent.'}
function safe(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmtSal(min,max){const e=n=>n?Math.round(n).toLocaleString('fr-FR')+' €':'';
  if(min&&max)return e(min)+' – '+e(max);if(min)return 'à partir de '+e(min);if(max)return 'jusqu’à '+e(max);return ''}
/* --------------------------------------- offre : dates, source, explication */
const SOURCE_LABELS={france_travail:'France Travail',adzuna:'Adzuna',linkedin:'LinkedIn',indeed:'Indeed',wttj:'Welcome to the Jungle',apec:'APEC',hellowork:'HelloWork',demo:'Démo',file:'Fichier local',lien:'Ajout manuel',labonnealternance:'La bonne alternance',career_pages:'Page carrières',search_engine:'Recherche web'};
const DECISION_LABELS={new:'À trier',retained:'Retenue',ignored:'Ignorée'};
const DECISION_FILTER_LABELS={new:'à trier',retained:'retenues',ignored:'ignorées'};
const DIM_LABELS=Object.fromEntries(WEIGHT_DIMS);
// Clés des filtres bloquants renvoyées par le scoring → libellé court.
const GATE_LABELS={contrat:'contrat',expérience:'expérience',localisation:'lieu',intitulé:'métier',salaire:'salaire',exclusions:'mot exclu'};
function parseDate(iso){if(!iso)return null;const d=new Date(String(iso).replace(/(\.\d{3})\d+/,'$1'));return isNaN(d)?null:d}
function fmtDate(iso,withTime){const d=parseDate(iso);if(!d)return '';return d.toLocaleDateString('fr-FR',withTime?{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}:{day:'2-digit',month:'2-digit',year:'numeric'})}
function fmtDateTime(iso){return fmtDate(iso,true)}
function sourceLabel(j){const s=j.explanation?.source;return SOURCE_LABELS[s]||s||''}
function toggleDetails(id){const el=$('details_'+id);if(!el)return;el.hidden=!el.hidden;const btn=document.querySelector('[data-toggle-details="'+id+'"]');if(btn){btn.setAttribute('aria-expanded',String(!el.hidden));btn.textContent=el.hidden?'Voir le détail':'Masquer le détail'}}
function scoreBreakdown(j){const e=j.explanation||{};const dims=e.dimensions||{};const keys=Object.keys(dims);if(!keys.length)return '';const weights=e.weights||{};const rows=keys.map(k=>{const value=Number(dims[k])||0;const weight=Math.round((Number(weights[k])||0)*100);return `<div class="score-dim"><span class="score-dim-label">${safe(DIM_LABELS[k]||k)}<em>${weight} %</em></span><span class="score-bar" aria-hidden="true"><i style="width:${Math.max(0,Math.min(100,value*10))}%"></i></span><b>${value.toLocaleString('fr-FR',{minimumFractionDigits:1,maximumFractionDigits:1})}</b></div>`}).join('');const gaps=(e.gaps||[]).slice(0,8);const indexAbsent=e.competences_source==='absente';const indexNote=indexAbsent?'<p class="hint">L’offre ne liste pas de compétences : le critère « Compétences » est compté à 5/10 par défaut.</p>':'';const prescore=Number(e.prescore);const note=!isNaN(prescore)&&prescore>0?`<p class="hint">Pré-note avant analyse détaillée : ${fmtScore(prescore)}/10.</p>`:'';const engine=e.scorer==='jev'?`<p class="hint">Critères notés par Jev${e.jev&&e.jev.model?' ('+safe(e.jev.model)+')':''}. Les critères impossibles à évaluer sont ignorés et leur poids est réparti sur les autres.</p>`:e.jev_error?`<p class="hint">Jev indisponible (${safe(e.jev_error)}) : note calculée localement.</p>`:'';return `<details class="details-block"><summary>Comment la note est calculée</summary><div class="score-breakdown">${rows}</div>${engine}${gaps.length?`<p class="hint">Demandées mais absentes de votre profil : ${safe(gaps.join(', '))}.</p>`:''}${indexNote}${note}</details>`}
function jobReason(j){const e=j.explanation||{};const gates=e.gates||{};const blocked=Object.keys(gates).filter(k=>gates[k]===false).map(k=>GATE_LABELS[k]||k);const parts=[];if(blocked.length)parts.push(`<b class="reason-warn">Critère non respecté : ${safe(blocked.join(', '))}</b> (note plafonnée à 3,9).`);const strengths=(e.strengths||[]).slice(0,5);if(strengths.length)parts.push('Compétences en commun : '+safe(strengths.join(', '))+'.');return parts.length?`<p class="job-reason">${parts.join(' ')}</p>`:''}
/* Le détail ne répète jamais ce qui est déjà visible dans la carte (entreprise, lieu,
   contrat, salaire, source, date) : il apporte l'information complémentaire. */
function detailBlock(j,inCard){const sectors=(j.sectors||[]).join(', ');const skills=(inCard&&(j.skills||[]).length<=6?[]:(j.skills||[])).map(s=>'<span class="skill">'+safe(s)+'</span>').join('');return `<div class="job-detail-body">${j.description?`<p class="job-description">${safe(j.description)}</p>`:'<p class="hint">La source ne fournit pas de description.</p>'}${skills?'<div class="chips">'+skills+'</div>':''}${sectors?`<ul class="detail-list"><li><strong>Secteurs</strong><span>${safe(sectors)}</span></li></ul>`:''}</div>${scoreBreakdown(j)}`}

async function decide(id,value){try{await api(`/api/jobs/${id}/decision?value=${value}`,{method:'POST'});loadJobs();loadOverview()}catch(e){message(e.message,'error')}}
/* ----------------------------------------------- liste des opportunités */
/* Carte d'offre : l'essentiel se lit en une ligne (entreprise, puis lieu · contrat ·
   salaire…), les actions secondaires à gauche du pied de carte, la décision à droite. */
function jobCard(j){const sal=fmtSal(j.salary_min,j.salary_max);const skillChips=(j.skills||[]).slice(0,6).map(s=>'<span class="skill">'+safe(s)+'</span>').join('');const decisionBadge=j.decision&&j.decision!=='new'?`<span class="decision ${safe(j.decision)}">${safe(DECISION_LABELS[j.decision]||j.decision)}</span>`:'';const appBadge=j.has_application?'<span class="badge ready" title="Une candidature existe pour cette offre">Candidature en cours</span>':'';const dimensions=j.explanation?.dimensions||{};const hasDetails=Boolean(j.description||(j.skills||[]).length||Object.keys(dimensions).length);const remote=j.remote?(/t[ée]l[ée]travail|remote|distance/i.test(j.remote)?j.remote:'Télétravail : '+j.remote):'';const sep='<span class="sep" aria-hidden="true">·</span>';const facts=[j.location,remote,j.contract_label||j.contract,j.experience_label,sal].filter(Boolean).map(safe).join(sep);const pub=publishedLabel(j);const origin=[pub?`<span title="${safe(fmtDate(j.published_at))}">${safe(pub)}</span>`:(j.created_at?`Ajoutée le ${safe(fmtDate(j.created_at))}`:''),sourcesInline(j)].filter(Boolean).join(sep);const checkBtn=j.url?`<button type="button" class="ghost small" onclick="checkJob(${j.id},this)" title="Vérifie si l'annonce est toujours publiée">Toujours en ligne ?</button>`:'';const toggle=j.decision==='ignored'?`<button type="button" class="ghost" onclick="decide(${j.id},'new')">Ne plus ignorer</button>`:`<button type="button" class="ghost" onclick="decide(${j.id},'ignored')">Ignorer</button>`;const detailsBtn=hasDetails?`<button type="button" class="ghost small details-toggle" data-toggle-details="${j.id}" aria-expanded="false" aria-controls="details_${j.id}" onclick="toggleDetails(${j.id})">Voir le détail</button>`:'';const linkBtn=j.url?`<a class="ghost link-btn small" href="${safe(j.url)}" target="_blank" rel="noopener">Voir l'annonce ↗</a>`:'';const primary=j.has_application?`<button type="button" class="primary" onclick="openDossier(${j.application_id},true)">Voir la candidature</button>`:j.decision==='retained'?`<button type="button" class="primary" onclick="createApplication(${j.id},this)" title="Prépare un pitch, un e-mail et un CV adaptés à cette offre">Préparer la candidature</button>`:`<button type="button" class="primary" onclick="decide(${j.id},'retained')">Retenir</button>`;return `<article class="job"><div class="score ${scoreClass(j.score)}" title="Note sur 10">${fmtScore(j.score)}<small>/10</small></div><div class="job-main"><div class="job-title"><h3>${safe(j.title)}</h3>${decisionBadge}${appBadge}</div>${j.company?`<p class="job-company">${safe(j.company)}</p>`:''}${facts?`<p class="job-facts">${facts}</p>`:''}${signalChips(j)}${skillChips?'<div class="chips">'+skillChips+'</div>':''}${jobReason(j)}${origin?`<p class="job-origin">${origin}</p>`:''}</div><div class="job-actions"><div class="actions-secondary">${detailsBtn}${linkBtn}${checkBtn}</div><div class="actions-primary">${toggle}${primary}</div></div>${hasDetails?`<div class="job-details" id="details_${j.id}" hidden>${detailBlock(j,true)}</div>`:''}</article>`}
function renderJobs(){const jobs=filteredJobs.slice(0,visibleJobs);const cards=jobs.map(jobCard).join('');const remaining=filteredJobs.length-visibleJobs;const more=remaining>0?`<div class="jobs-footer"><button type="button" class="ghost" onclick="showMoreJobs()">Afficher ${plural(Math.min(30,remaining),'offre')} de plus</button></div>`:'';const empty=allJobs.length?'<div class="empty"><p>Aucune offre ne correspond à ces filtres.</p><button type="button" class="ghost small" onclick="resetJobFilters()">Réinitialiser les filtres</button></div>':'<div class="empty"><p>Aucune offre pour l’instant.</p><p class="hint">Lancez la veille pour récupérer des offres, ou ajoutez-en une à partir de son lien.</p></div>';$('jobList').innerHTML=cards?cards+more:empty;updateJobsCount(jobs.length)}
let allJobs=[];let filteredJobs=[];let visibleJobs=30;let jobFilterTimer=null;
function jobsFilterState(){return{minScore:Number($('minScore')?.value||0)||0,decision:$('decisionFilter')?.value||'',application:$('applicationFilter')?.value||'',sort:$('sortFilter')?.value||'score',showOld:Boolean($('showOld')?.checked)}}
const SIGNAL_ICONS={hourglass:'<path d="M6.5 7h11"/><path d="M6 20v-2a6 6 0 1 1 12 0v2a1 1 0 0 1-1 1H7a1 1 0 0 1-1-1z"/><path d="M6 4v2a6 6 0 1 0 12 0V4a1 1 0 0 0-1-1H7a1 1 0 0 0-1 1z"/>',bolt:'<path d="M13 3v7h6l-8 11v-7H5l8-11"/>',alert:'<path d="M12 9v4"/><path d="M10.36 3.59 2.26 17.13a1.9 1.9 0 0 0 1.63 2.87h16.22a1.9 1.9 0 0 0 1.63-2.87L13.64 3.59a1.9 1.9 0 0 0-3.28 0z"/><path d="M12 16h.01"/>',check:'<path d="M3 12a9 9 0 1 0 18 0a9 9 0 1 0-18 0"/><path d="m9 12 2 2 4-4"/>',stack:'<path d="m12 4-8 4 8 4 8-4-8-4"/><path d="m4 12 8 4 8-4"/><path d="m4 16 8 4 8-4"/>',ended:'<path d="M3 12a9 9 0 1 0 18 0a9 9 0 1 0-18 0"/><path d="m10 10 4 4m0-4-4 4"/>'};
function signalChips(j){const list=(j.signals||[]).slice(0,3);if(!list.length)return '';return `<div class="signals">${list.map(s=>`<span class="sig ${safe(s.level)}" title="${safe(s.title||s.label)}"><svg viewBox="0 0 24 24" aria-hidden="true">${SIGNAL_ICONS[s.icon]||''}</svg>${safe(s.label)}</span>`).join('')}</div>`}
function isPresented(j){return !j.freshness||j.freshness.fresh||j.decision==='retained'||j.has_application}
function publishedLabel(j){const live=j.freshness&&j.freshness.basis==='en_ligne';const d=parseDate(j.published_at);if(!d)return live?'Toujours en ligne':'';const days=Math.max(0,Math.floor((Date.now()-d.getTime())/86400000));return days===0?'Publiée aujourd’hui':days===1?'Publiée hier':`Publiée il y a ${days} jours`}
function sourcesInline(j){const list=(j.sources||[]).filter(s=>s.source||s.url);if(!list.length){const s=sourceLabel(j);return s?'Source : '+safe(s):''}const items=list.map(s=>{const label=SOURCE_LABELS[s.source]||s.source||'site';return s.url?`<a href="${safe(s.url)}" target="_blank" rel="noopener">${safe(label)}</a>`:safe(label)}).join(', ');return `${list.length>1?'Sources':'Source'} : ${items}`}
async function checkJob(id,btn){const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Vérification…'}try{const r=await api(`/api/jobs/${id}/check`,{method:'POST'});message(r.status==='expired'?`Offre expirée (${r.reason}) : elle est désormais masquée.`:r.status==='active'?'L’offre est toujours en ligne.':`Vérification impossible : ${r.reason}`,r.status==='expired'?'error':'ok');await Promise.all([loadJobs(),loadOverview()])}catch(e){message(e.message,'error')}finally{if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent=idle}}}
function sortJobs(list){const mode=jobsFilterState().sort;const copy=[...list];if(mode==='date')return copy.sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));if(mode==='published')return copy.sort((a,b)=>String(b.published_at||b.created_at||'').localeCompare(String(a.published_at||a.created_at||'')));if(mode==='title')return copy.sort((a,b)=>String(a.title||'').localeCompare(String(b.title||''),'fr'));return copy.sort((a,b)=>(b.score??-1)-(a.score??-1))}
function updateJobsCount(shown){const box=$('jobsFilterCount');if(!box)return;const f=jobsFilterState();const best=allJobs.reduce((m,j)=>Math.max(m,j.score??0),0);const total=filteredJobs.length;const active=[];if(f.minScore)active.push('note ≥ '+fmtScore(f.minScore));if(f.decision)active.push(DECISION_FILTER_LABELS[f.decision]||f.decision);if(f.application)active.push(f.application==='yes'?'avec candidature':'sans candidature');const hiddenOld=f.showOld?0:allJobs.filter(j=>!isPresented(j)).length;const parts=[total>shown?`${shown} affichées sur ${plural(total,'offre')}`:plural(total,'offre')];if(active.length)parts.push('filtres : '+active.join(', '));if(hiddenOld)parts.push(plural(hiddenOld,'offre ancienne masquée','offres anciennes masquées'));if(f.minScore>best)parts.push(`meilleure note disponible : ${fmtScore(best)}/10`);box.hidden=false;box.textContent=parts.join(' · ')}
function applyJobFilters(){const f=jobsFilterState();filteredJobs=sortJobs(allJobs.filter(j=>{if(!f.showOld&&!isPresented(j))return false;if(f.minScore&&(j.score??0)<f.minScore)return false;if(f.decision&&j.decision!==f.decision)return false;if(f.application==='yes'&&!j.has_application)return false;if(f.application==='no'&&j.has_application)return false;return true}));visibleJobs=30;renderJobs()}
function resetJobFilters(){resetJobFilterFields();applyJobFilters()}
// Raccourcis depuis les indicateurs et la liste « À faire » : filtre préréglé + onglet Offres.
function showRetained(){resetJobFilterFields();$('decisionFilter').value='retained';applyJobFilters();showTab('market')}
function showHighScores(){resetJobFilterFields();$('minScore').value='7';applyJobFilters();showTab('market')}
function resetJobFilterFields(){[['minScore','0'],['decisionFilter',''],['applicationFilter',''],['sortFilter','score']].forEach(([id,v])=>{const el=$(id);if(el)el.value=v});if($('showOld'))$('showOld').checked=false}
let jobFiltersBound=false;
function bindJobFilters(){if(jobFiltersBound)return;jobFiltersBound=true;['minScore','decisionFilter','applicationFilter','sortFilter','showOld'].forEach(id=>{const el=$(id);if(!el)return;const live=id==='minScore';el.addEventListener(live?'input':'change',()=>{clearTimeout(jobFilterTimer);jobFilterTimer=setTimeout(applyJobFilters,live?180:0)})})}
function showMoreJobs(){visibleJobs+=30;renderJobs()}
async function loadJobs(){try{allJobs=await api('/api/jobs?include_old=true')}catch(e){message(e.message,'error');allJobs=[]}applyJobFilters()}
async function createApplication(jobId,btn){const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Préparation…'}agentFeedStart('Préparation de la candidature');try{const r=await streamPost('/api/applications/candidater/stream?job_id='+jobId,{method:'POST'},evt=>{if(evt.type==='progress')agentFeedEvent(evt)});agentFeedStep('Candidature prête : pitch, e-mail et CV rédigés.','done');agentFeedFinish();message('Candidature préparée. Relisez le pitch, l’e-mail et le CV avant de l’approuver.');await Promise.all([loadApplications(),loadOverview()]);loadKanban();loadJobs();openDossier(r.id,true)}catch(e){message(e.message,'error');agentFeedStep(e.message,'error');agentFeedFinish('error')}finally{if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent=idle}}}
let allApplications=[];let currentDossierId=null;
function dossierLabel(a){const j=a.job||{};const title=j.title||a.email_subject||'Candidature sans titre';const co=j.company?` · ${j.company}`:'';return `${title}${co} — ${STATUS_LABELS[a.status]||a.status}`}
async function loadApplications(){const apps=await api('/api/applications');allApplications=apps||[];const wrap=$('dossierPickerWrap');if(wrap)wrap.hidden=allApplications.length<2;const picker=$('dossierPicker');if(picker){const prev=picker.value||String(currentDossierId||'');picker.innerHTML='<option value="">Choisir une candidature…</option>'+allApplications.map(a=>`<option value="${a.id}">${safe(dossierLabel(a))}</option>`).join('');if(prev&&allApplications.some(a=>String(a.id)===String(prev)))picker.value=prev}
if(currentDossierId&&!allApplications.some(a=>a.id===currentDossierId))currentDossierId=null;
if(!currentDossierId&&allApplications.length)currentDossierId=allApplications[0].id;
if(picker&&currentDossierId)picker.value=String(currentDossierId);
renderDossier();renderApplicationList()}
async function scheduleFollowupThenRefresh(id){try{await api('/api/applications/'+id+'/followup',{method:'POST'});message('Relance planifiée. Approuvez-la avant tout envoi.');const fresh=await api('/api/applications/'+id);const i=allApplications.findIndex(a=>a.id===id);if(i>=0)allApplications[i]=fresh;renderDossier();renderApplicationList();loadKanban()}catch(e){message(e.message,'error')}}
async function approveFollowupThenRefresh(id){try{await api('/api/applications/'+id+'/followup/approve',{method:'POST'});message('Relance approuvée.');const fresh=await api('/api/applications/'+id);const i=allApplications.findIndex(a=>a.id===id);if(i>=0)allApplications[i]=fresh;renderDossier();renderApplicationList();loadKanban()}catch(e){message(e.message,'error')}}
async function setState(id,state){try{await api('/api/applications/'+id+'/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state})});message(state==='approved'?'Candidature approuvée. Vous pouvez préparer le brouillon d’e-mail.':'Candidature rejetée.');loadApplications()}catch(e){message(e.message,'error')}}
async function emailDraft(id){try{await api('/api/applications/'+id+'/email-draft',{method:'POST'});message('Brouillon d’e-mail prêt. Aucun e-mail n’a été envoyé.');loadApplications()}catch(e){message(e.message,'error')}}
const KANBAN_COLUMNS=['draft','submitted','screening','interview','offer','rejected','withdrawn','closed'];
// Étapes toujours visibles du tableau ; les étapes de clôture n'apparaissent que si
// elles contiennent une carte (ou à la demande).
const MAIN_COLUMNS=['draft','submitted','screening','interview','offer'];
const STATUS_LABELS={draft:'À envoyer',submitted:'Envoyée',screening:'Présélection',interview:'Entretien',offer:'Offre reçue',rejected:'Refusée',withdrawn:'Retirée',closed:'Clôturée'};
/* --------------------------------------- dossier : statuts, badges, dates */
const STATE_LABELS={draft:'Brouillon',to_validate:'À valider',approved:'Approuvée',rejected:'Rejetée',email_draft_created:'E-mail prêt',sent:'Envoyée'};
const RELANCE_TEXT={none:'Aucune relance prévue',pending_approval:'Relance à approuver',approved:'Relance approuvée'};
function stateBadge(state){return `<span class="badge state-${safe(state)}" title="Validation de la candidature">${safe(STATE_LABELS[state]||state)}</span>`}
function historyOf(a){return Array.isArray(a?.history)?a.history:[]}
function lastHistory(a,kinds){const list=kinds?historyOf(a).filter(h=>kinds.includes(h.kind)):historyOf(a);return list.length?list[list.length-1]:null}
function dossierCreatedAt(a){const entry=historyOf(a).find(h=>h.kind==='application_created');return entry?entry.at:null}
function dossierDates(a){const j=a.job||{};const moved=lastHistory(a,['status_changed','state_change','email_sent']);return [['Offre ajoutée le',fmtDateTime(j.created_at)],['Candidature créée le',fmtDateTime(dossierCreatedAt(a))],['Dernière mise à jour',moved?fmtDateTime(moved.at):'']].filter(([,v])=>v)}
function dossierDatesList(a){const rows=dossierDates(a).map(([k,v])=>`<li><strong>${safe(k)}</strong><span>${safe(v)}</span></li>`).join('');return rows?`<ul class="detail-list dossier-dates">${rows}</ul>`:''}
function timeline(a){const list=historyOf(a);if(!list.length)return '<p class="hint">Aucun événement pour l’instant.</p>';return `<ol class="timeline">${list.map((h,i)=>`<li class="${i===list.length-1?'current':''}"><time datetime="${safe(h.at||'')}">${safe(fmtDateTime(h.at)||'date inconnue')}</time><span>${safe(h.label)}</span></li>`).join('')}</ol>`}
function relanceSummary(a){const due=fmtDate(a.followup_due_at);const base=RELANCE_TEXT[a.followup_state]||a.followup_state;return due?`${base} (échéance : ${due})`:base}
/* Carte du tableau : cliquable (ou Entrée au clavier) pour ouvrir la candidature ; une
   seule action contextuelle, la relance, proposée seulement une fois la candidature envoyée. */
function kanbanCard(c){const followable=['submitted','screening','interview'].includes(c.status);const relance=c.followup_state==='pending_approval'?'<span class="badge warn">Relance à approuver</span>':c.followup_state==='approved'?`<span class="badge">Relance ${c.followup_due_at?'le '+safe(fmtDate(c.followup_due_at)):'prévue'}</span>`:'';const score=c.score!=null?`<span class="kanban-score ${scoreClass(c.score)}">${fmtScore(c.score)}/10</span>`:'';const updated=c.status_updated_at||c.application_created_at;const action=c.followup_state==='pending_approval'?`<button type="button" class="primary small" onclick="approveFollowup(${c.id})">Approuver la relance</button>`:followable&&c.followup_state!=='approved'?`<button type="button" class="ghost small" onclick="scheduleFollowup(${c.id})">Planifier une relance</button>`:'';return `<article class="kanban-card" draggable="true" tabindex="0" ondragstart="kanbanDragStart(event,${c.id})" onclick="openDossier(${c.id},true)" onkeydown="if(event.key==='Enter'&&event.target===this)openDossier(${c.id},true)" title="Ouvrir la candidature"><div class="kanban-card-head"><strong>${safe(c.job_title||'Offre inconnue')}</strong><small>${safe(c.company||'Entreprise non précisée')}${c.location?' · '+safe(c.location):''}</small></div>${score||relance?`<div class="kanban-tags">${score}${relance}</div>`:''}${updated?`<small class="kanban-dates">Mise à jour le ${safe(fmtDate(updated))}</small>`:''}${action?`<div class="kanban-actions" onclick="event.stopPropagation()">${action}</div>`:''}</article>`}
let kanbanCards=[];
async function loadKanban(){try{const k=await api('/api/kanban');kanbanCards=k.cards||[];renderKanban();lastReport=await api('/api/report');renderTrackingTodo()}catch(e){message(e.message,'error')}}
let showAllKanbanColumns=false;
const EMPTY_APPLICATIONS='<div class="empty"><p>Aucune candidature pour l’instant.</p><p class="hint">Retenez une offre dans l’onglet « Offres », puis cliquez sur « Préparer la candidature ».</p><button type="button" class="ghost small" onclick="showTab(\'market\')">Voir les offres</button></div>';
function renderKanban(){const board=$('kanbanBoard');if(!kanbanCards.length){board.innerHTML=EMPTY_APPLICATIONS;return}const active=new Set(kanbanCards.map(c=>c.status));const hiddenClosed=KANBAN_COLUMNS.filter(s=>!MAIN_COLUMNS.includes(s)&&!active.has(s));const columns=showAllKanbanColumns?KANBAN_COLUMNS:KANBAN_COLUMNS.filter(s=>MAIN_COLUMNS.includes(s)||active.has(s));const cols=columns.map(s=>{const cards=kanbanCards.filter(c=>c.status===s);return `<div class="kanban-col" data-status="${s}" ondragover="kanbanOver(event)" ondragleave="kanbanOut(event)" ondrop="kanbanDrop(event,'${s}')"><h4>${STATUS_LABELS[s]} <span class="kanban-count">${cards.length}</span></h4><div class="kanban-cards">${cards.map(kanbanCard).join('')||'<div class="kanban-empty">Aucune</div>'}</div></div>`}).join('');const toggle=hiddenClosed.length?`<button type="button" class="ghost small" onclick="toggleKanbanColumns()">${showAllKanbanColumns?'Masquer les étapes de clôture vides':'Afficher les étapes de clôture'}</button>`:'';board.innerHTML=`<div class="kanban-toolbar"><span class="hint">${plural(kanbanCards.length,'candidature suivie','candidatures suivies')}</span>${toggle}</div><div class="kanban-columns">${cols}</div>`}
function toggleKanbanColumns(){showAllKanbanColumns=!showAllKanbanColumns;renderKanban()}
function renderTrackingTodo(){const box=$('trackingTodo');if(!box)return;const o=lastOverview||{},rep=lastReport||{};const apps=(typeof allApplications!=='undefined'?allApplications:[])||[];const offers=o.high_score_count||0;const followups=rep.due_followups||0;const toValidate=o.to_validate_count!=null?o.to_validate_count:apps.filter(a=>a.state==='to_validate').length;const item=(n,one,many,onclick)=>`<button type="button" class="todo-item" onclick="${onclick}"><strong>${n}</strong><span>${n>1?many:one}</span></button>`;const items=[];if(offers>0)items.push(item(offers,'offre notée 7/10 ou plus','offres notées 7/10 ou plus','showHighScores()'));if(followups>0)items.push(item(followups,'relance à traiter','relances à traiter',"showTab('tracking')"));if(toValidate>0)items.push(item(toValidate,'candidature à valider','candidatures à valider',"showTab('applications')"));if(!items.length){box.hidden=true;box.innerHTML='';return}box.hidden=false;box.innerHTML=`<div class="todo-title">À faire</div><div class="todo-items">${items.join('')}</div>`}
let kanbanDragId=null;
function kanbanDragStart(ev,id){kanbanDragId=id;ev.dataTransfer.effectAllowed='move';try{ev.dataTransfer.setData('text/plain',String(id))}catch(x){}}
function kanbanOver(ev){ev.preventDefault();ev.currentTarget.classList.add('over')}
function kanbanOut(ev){ev.currentTarget.classList.remove('over')}
function kanbanDrop(ev,status){ev.preventDefault();ev.currentTarget.classList.remove('over');const id=Number(ev.dataTransfer.getData('text/plain'))||kanbanDragId;moveCard(id,status)}
async function moveCard(id,status){const card=kanbanCards.find(c=>c.id===id);if(!card||card.status===status)return;const prev=card.status;card.status=status;renderKanban();try{await api(`/api/applications/${id}/status?status=${status}`,{method:'POST'});message(`« ${card.job_title||'Candidature'} » : étape « ${STATUS_LABELS[status]||status} ».`);lastReport=await api('/api/report');renderTrackingTodo();loadApplications()}catch(e){card.status=prev;renderKanban();message(e.message,'error')}}
async function scheduleFollowup(id){try{await api(`/api/applications/${id}/followup`,{method:'POST'});message('Relance planifiée. Approuvez-la avant tout envoi.');loadKanban()}catch(e){message(e.message,'error')}}
async function approveFollowup(id){try{await api(`/api/applications/${id}/followup/approve`,{method:'POST'});message('Relance approuvée.');loadKanban()}catch(e){message(e.message,'error')}}
function goApplications(id){openDossier(id,true)}
async function openDossier(id,switchTab){if(!id)return;currentDossierId=Number(id);const picker=$('dossierPicker');if(picker)picker.value=String(currentDossierId);try{const fresh=await api('/api/applications/'+currentDossierId);const i=allApplications.findIndex(a=>a.id===currentDossierId);if(i>=0)allApplications[i]=fresh;else allApplications.unshift(fresh)}catch(e){}
if(switchTab)showTab('applications');
renderDossier();renderApplicationList();
requestAnimationFrame(()=>{const v=$('dossierView');if(v&&switchTab)v.scrollIntoView({behavior:'smooth',block:'start'})})}
function currentDossier(){return allApplications.find(a=>a.id===currentDossierId)||null}
// La navigation entre candidatures passe par le sélecteur (affiché dès 2 candidatures) ;
// cette zone ne sert plus qu'à l'état vide.
function renderApplicationList(){const box=$('applicationList');if(!box)return;box.innerHTML=allApplications.length?'':EMPTY_APPLICATIONS}
function dossierField(id,suffix){const el=$('dossier_'+suffix+'_'+id);return el?el.value:''}
async function saveDossierSilent(id){const body={pitch:dossierField(id,'pitch'),email_subject:dossierField(id,'subject'),email_body:dossierField(id,'body'),cv_after:dossierField(id,'cv'),skills_to_highlight:dossierField(id,'skills').split(/[\n,]+/).map(s=>s.trim()).filter(Boolean)};const updated=await api('/api/applications/'+id+'/content',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const i=allApplications.findIndex(a=>a.id===id);if(i>=0)allApplications[i]=updated;return updated}
async function saveDossier(id,btn){const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Enregistrement…'}try{await saveDossierSilent(id);renderDossier();renderApplicationList();message('Modifications enregistrées.')}catch(e){message(e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent=idle}}}
async function regenerateDossier(id,btn){if(!confirm('Remplacer le pitch et le CV actuels par une nouvelle version ? Vos modifications non enregistrées seront perdues.'))return;const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Régénération…'}agentFeedStart('Nouvelle version des textes');try{const r=await streamPost('/api/applications/'+id+'/generate/stream',{method:'POST'},evt=>{if(evt.type==='progress')agentFeedEvent(evt)});const i=allApplications.findIndex(a=>a.id===id);if(i>=0)allApplications[i]=r;agentFeedStep('Nouvelle version prête.','done');agentFeedFinish();renderDossier();renderApplicationList();message('Nouvelle version prête. Relisez-la avant d’approuver la candidature.')}catch(e){agentFeedStep(e.message,'error');agentFeedFinish('error');message(e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent=idle}}}
async function aiRefineDossier(id,btn){const promptEl=$('dossier_ai_prompt_'+id);const targetEl=$('dossier_ai_target_'+id);const prompt=promptEl?promptEl.value:'';const target=targetEl?targetEl.value:'pitch';if(!prompt.trim()){message('Décrivez d’abord la modification souhaitée.','error');if(promptEl)promptEl.focus();return}const statusEl=$('dossier_ai_status_'+id);const idle=btn?btn.textContent:'';if(btn){btn.disabled=true;btn.textContent='Réécriture…'}if(statusEl)statusEl.textContent='Enregistrement de vos textes…';try{await saveDossierSilent(id);if(statusEl)statusEl.textContent='Réécriture en cours (rédaction, puis relecture)…';const r=await api('/api/applications/'+id+'/refine/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({comments:prompt,document_type:target})});if(r.application){const i=allApplications.findIndex(a=>a.id===id);if(i>=0)allApplications[i]=r.application;renderDossier();renderApplicationList()}const note=(r.score!=null)?`Note de relecture : ${fmtScore(r.score)}/10 après ${plural(r.iterations,'passe')}.`:'Réécriture terminée.';if(statusEl)statusEl.textContent=note+' Relisez le texte avant d’approuver.';message('Texte réécrit. '+note)}catch(e){if(statusEl)statusEl.textContent='';message(e.message,'error')}finally{if(btn){btn.disabled=false;btn.textContent=idle}}}
async function moveCardDossier(id,status){try{await api('/api/applications/'+id+'/status?status='+status,{method:'POST'});message('Étape mise à jour : « '+(STATUS_LABELS[status]||status)+' ».');const fresh=await api('/api/applications/'+id);const i=allApplications.findIndex(a=>a.id===id);if(i>=0)allApplications[i]=fresh;renderDossier();renderApplicationList();loadKanban()}catch(e){message(e.message,'error')}}
/* ------------------------------------------- vue dossier (annonce + textes) */
function renderJobPanel(a,j){if(!j.title)return '<section class="dossier-panel dossier-job"><h4>L’offre</h4><p class="hint">Offre introuvable.</p></section>';const open=j.url?`<a class="ghost link-btn small" href="${safe(j.url)}" target="_blank" rel="noopener">Voir l'annonce ↗</a>`:'';return `<section class="dossier-panel dossier-job"><div class="dossier-panel-head"><h4>L’offre</h4>${open}</div>${dossierDatesList(a)}${detailBlock(j)}${a.quality?.warnings?.length?`<small class="warning">${safe(a.quality.warnings.join(' · '))}</small>`:''}</section>`}
function renderTimelinePanel(a){return `<section class="dossier-panel dossier-timeline"><h4>Historique</h4>${timeline(a)}</section>`}
function renderDossierHead(a,j,sal){const title=j.title||a.email_subject||'Candidature à préparer';const meta=[j.company||'Entreprise non précisée',j.location,j.contract,sal,j.score!=null?`${fmtScore(j.score)}/10`:''].filter(Boolean).map(safe).join(' · ');return `<div class="dossier-head"><div><span class="eyebrow">Candidature #${a.id}</span><h3>${safe(title)}</h3><p class="hint">${meta}</p></div><div class="dossier-head-side">${stateBadge(a.state)}<label class="status-select"><span>Étape</span><select class="select" onchange="moveCardDossier(${a.id},this.value)">${KANBAN_COLUMNS.map(s=>`<option value="${s}" ${a.status===s?'selected':''}>${STATUS_LABELS[s]}</option>`).join('')}</select></label></div></div>`}
function renderDossierApp(a,j){const relanceBtns=a.followup_state==='pending_approval'?`<button type="button" class="primary" onclick="approveFollowupThenRefresh(${a.id})">Approuver la relance</button>`:['submitted','screening','interview'].includes(a.status)?`<button type="button" class="ghost" onclick="scheduleFollowupThenRefresh(${a.id})">Planifier une relance</button>`:'';const stateBtns=a.state==='to_validate'?`<button type="button" class="ghost" onclick="setState(${a.id},'rejected')">Rejeter</button><button type="button" class="primary" onclick="setState(${a.id},'approved')">Approuver la candidature</button>`:a.state==='approved'?`<button type="button" class="primary" onclick="emailDraft(${a.id})">Préparer le brouillon d’e-mail</button>`:'';const summary=[relanceSummary(a),a.submitted_at?`envoyée le ${fmtDateTime(a.submitted_at)}`:''].filter(Boolean).join(' · ');return `<section class="dossier-panel dossier-app"><h4>Vos textes</h4><label class="field"><span>Pitch (2 à 4 phrases)</span><textarea id="dossier_pitch_${a.id}" rows="5"></textarea></label><fieldset class="field-group"><legend>E-mail de candidature</legend><label class="field"><span>Objet</span><input id="dossier_subject_${a.id}" value=""></label><label class="field"><span>Message</span><textarea id="dossier_body_${a.id}" rows="8"></textarea></label></fieldset><label class="field"><span>CV adapté (format ATS)</span><textarea id="dossier_cv_${a.id}" rows="12"></textarea></label><label class="field"><span>Compétences à mettre en avant</span><textarea id="dossier_skills_${a.id}" rows="4" data-autosize-max="220"></textarea><small class="hint">Une par ligne.</small></label><div class="form-actions"><button type="button" class="ghost" onclick="regenerateDossier(${a.id},this)" title="Remplace le pitch et le CV par une nouvelle version">Régénérer pitch et CV</button><button type="button" class="primary" onclick="saveDossier(${a.id},this)">Enregistrer</button></div><div class="ai-box"><h4>Retoucher avec l’IA</h4><p class="hint">Exemple : « Rends le pitch plus direct et cite la compétence clé de l’offre. » L’IA part de vos textes et de l’offre affichée à côté.</p><div class="ai-row"><select id="dossier_ai_target_${a.id}" class="select" aria-label="Texte à retoucher"><option value="pitch">Pitch</option><option value="cv_ats">CV</option></select><input id="dossier_ai_prompt_${a.id}" placeholder="Votre consigne…" aria-label="Consigne pour l’IA" onkeydown="if(event.key==='Enter'){event.preventDefault();aiRefineDossier(${a.id},this.nextElementSibling)}"><button type="button" class="primary" onclick="aiRefineDossier(${a.id},this)">Réécrire</button></div><small id="dossier_ai_status_${a.id}" class="hint"></small></div><div class="dossier-status"><p class="dossier-status-text">${safe(summary)}</p>${relanceBtns||stateBtns?`<div class="actions">${relanceBtns}${stateBtns}</div>`:''}</div></section>`}
function renderDossier(){const view=$('dossierView');if(!view)return;const a=currentDossier();if(!a){view.hidden=true;view.innerHTML='';return}
const j=a.job||{};const sal=fmtSal(j.salary_min,j.salary_max);
view.hidden=false;
view.innerHTML=`<article class="card dossier-card" id="dossier_${a.id}">${renderDossierHead(a,j,sal)}<div class="dossier-grid"><div class="dossier-side">${renderJobPanel(a,j)}${renderTimelinePanel(a)}</div>${renderDossierApp(a,j)}</div></article>`;
fillDossierFields(a)}
boot()
function fillDossierFields(a){const set=(s,v)=>{const el=$(s);if(el)el.value=v||''};set('dossier_subject_'+a.id,a.email_subject);set('dossier_pitch_'+a.id,a.pitch);set('dossier_body_'+a.id,a.email_body);set('dossier_cv_'+a.id,a.cv_after);set('dossier_skills_'+a.id,(a.skills_to_highlight||[]).join('\n'));autoSizeDossierTextareas()}
